    <footer class="py-8 px-4 bg-surface-light border-t border-gray-200 dark:border-gray-800">
        <div class="container mx-auto max-w-6xl">
            <div class="flex flex-col md:flex-row justify-between items-center">
                <div class="mb-6 md:mb-0">
                    <div class="flex items-center space-x-2">
                        <div class="w-6 h-6 rounded-full bg-gradient-to-r from-blue-500 to-purple-500"></div>
                        <span class="text-lg font-heading font-bold text-primary">Alex Chen</span>
                    </div>
                    <p class="text-sm text-secondary mt-2">© 2024 All rights reserved.</p>
                </div>

                <div class="flex space-x-6">
                    <a href="#" class="text-secondary hover:text-accent transition-colors duration-200">Twitter</a>
                    <a href="#" class="text-secondary hover:text-accent transition-colors duration-200">GitHub</a>
                    <a href="#" class="text-secondary hover:text-accent transition-colors duration-200">LinkedIn</a>
                    <a href="#" class="text-secondary hover:text-accent transition-colors duration-200">Email</a>
