    <!-- JavaScript -->
    <script>
        // Dark mode toggle functionality
        function toggleDarkMode() {
            const html = document.documentElement;
            const isDark = html.classList.toggle('dark');

            // Update icons
            document.getElementById('sunIcon').classList.toggle('hidden', isDark);
            document.getElementById('moonIcon').classList.toggle('hidden', !isDark);
            document.getElementById('sunIconMobile').classList.toggle('hidden', isDark);
            document.getElementById('moonIconMobile').classList.toggle('hidden', !isDark);

            // Update text
            const textElement = document.getElementById('darkModeTextMobile');
            if (textElement) {
                textElement.textContent = isDark ? 'Light Mode' : 'Dark Mode';
            }

            // Save preference
            localStorage.setItem('darkMode', isDark);
        }

        // Initialize dark mode
        function initDarkMode() {
            const savedMode = localStorage.getItem('darkMode');
            const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

            if (savedMode === 'true' || (!savedMode && prefersDark)) {
                document.documentElement.classList.add('dark');
                document.getElementById('sunIcon').classList.add('hidden');
                document.getElementById('moonIcon').classList.remove('hidden');
                document.getElementById('sunIconMobile').classList.add('hidden');
                document.getElementById('moonIconMobile').classList.remove('hidden');
                const textElement = document.getElementById('darkModeTextMobile');
                if (textElement) {
                    textElement.textContent = 'Light Mode';
                }
            }
        }

        // Mobile menu toggle
        function toggleMobileMenu() {
            const menu = document.getElementById('mobileMenu');
            menu.classList.toggle('hidden');
        }

        // Newsletter form submission
        function handleNewsletterSubmit(e) {
            e.preventDefault();
            const email = document.getElementById('newsletter-email').value;

            // Simple validation
            if (!email || !email.includes('@')) {
                alert('Please enter a valid email address.');
                return;
            }

            // In a real app, you would send this to your backend
            alert(`Thank you for subscribing with: ${email}`);
            document.getElementById('newsletterForm').reset();
        }

        // Event listeners
        document.addEventListener('DOMContentLoaded', () => {
            initDarkMode();

            // Dark mode toggles
            document.getElementById('darkModeToggle').addEventListener('click', toggleDarkMode);
            document.getElementById('darkModeToggleMobile').addEventListener('click', toggleDarkMode);

            // Mobile menu
            document.getElementById('mobileMenuButton').addEventListener('click', toggleMobileMenu);

            // Newsletter form
            document.getElementById('newsletterForm').addEventListener('submit', handleNewsletterSubmit);

            // Smooth scrolling for anchor links
            document.querySelectorAll('a[href^="#"]').forEach(anchor => {
                anchor.addEventListener('click', function(e) {
                    e.preventDefault();
                    const targetId = this.getAttribute('href');
                    if (targetId === '#') return;

                    const targetElement = document.querySelector(targetId);
                    if (targetElement) {
                        targetElement.scrollIntoView({
                            behavior: 'smooth',
                            block: 'start'
                        });

                        // Close mobile menu if open
                        const mobileMenu = document.getElementById('mobileMenu');
                        if (!mobileMenu.classList.contains('hidden')) {
                            mobileMenu.classList.add('hidden');
                        }
                    }
                });
            });
        });
    </script>
